# Disable alarms corresponding to coworker cancellation emails
# Expect existing variables: cancel_threads, all_alarms, phone_token, all_contacts

def require_global(name):
    if name not in globals() or globals()[name] is None:
        raise Exception(f'missing_global_{name}')

for var in ['cancel_threads','all_alarms','phone_token','all_contacts']:
    require_global(var)

coworker_email_to_name = {}
for c in all_contacts:
    email = c.get('email')
    if email:
        coworker_email_to_name[email] = (c.get('first_name') or '') + ((' '+c.get('last_name')) if c.get('last_name') else '')

cancel_emails = []
for t in cancel_threads:
    parts = t.get('participants') or []
    for p in parts:
        email = p.get('email')
        if email and email != 'jamie-solomon@gmail.com':
            cancel_emails.append(email)

cancel_emails = sorted(set(cancel_emails))
print('cancel_emails', cancel_emails)
print('cancel_email_to_names', {e: coworker_email_to_name.get(e) for e in cancel_emails})

# Determine first names to match alarm labels
cancel_first_names = set()
for e in cancel_emails:
    nm = coworker_email_to_name.get(e,'')
    first = (nm.split(' ')[0] if nm else '')
    if first:
        cancel_first_names.add(first)
print('cancel_first_names', cancel_first_names)

# Find enabled alarms whose label contains these first names (case-insensitive)
alarms_to_disable = []
for a in all_alarms:
    if a.get('enabled') is True:
        label = a.get('label','') or ''
        for fn in cancel_first_names:
            if fn and fn.lower() in label.lower():
                alarms_to_disable.append(a)
                break

print('alarms_to_disable_count', len(alarms_to_disable))
print('alarms_to_disable', [(a['alarm_id'], a.get('label'), a.get('time'), a.get('repeat_days')) for a in alarms_to_disable])

# Disable them
update_results = []
for a in alarms_to_disable:
    alarm_id = a['alarm_id']
    res = apis.phone.update_alarm(alarm_id=alarm_id, access_token=phone_token, enabled=False)
    update_results.append((alarm_id, res))

print('update_results', update_results)

